def outside_and_enclosed(i):
    h,w=len(i),len(i[0]); vis={(0,0)}; q=deque([(0,0)])
    for c in range(w):
        if i[0][c]==0 and (0,c) not in vis: vis.add((0,c)); q.append((0,c))
    for c in range(w):
        if i[h-1][c]==0 and (h-1,c) not in vis: vis.add((h-1,c)); q.append((h-1,c))
    for r in range(h):
        if i[r][0]==0 and (r,0) not in vis: vis.add((r,0)); q.append((r,0))
        if i[r][w-1]==0 and (r,w-1) not in vis: vis.add((r,w-1)); q.append((r,w-1))
    while q:
