    while True:
        rr0=r1-k*step[0]; cc0=c1-k*step[1]
        rr1=r3+k*step[0]; cc1=c3+k*step[1]
        rows_lo,rows_hi=sorted([rr0,rr1]); cols_lo,cols_hi=sorted([cc0,cc1])
