        for c in range(max(0,cols_lo), min(w,cols_hi+1)):
            for rr in (rows_lo,rows_hi):
                if 0<=rr<h and 0<=c<w: O[rr][c]=1
        k+=1
        if k>100 or rows_hi<-1 or cc1<-1 or rows_lo>w or cc0>w: break
